37	/**
38	 * Mostly used as a facade for all Petclinic controllers
39	 * Also a placeholder for @Transactional and @Cacheable annotations
40	 *
41	 * @author Michael Isvy
42	 * @author Vitaliy Fedoriv
43	 */
44	@Service
45	public class ClinicServiceImpl implements ClinicService {
46	
47	    private final PetRepository petRepository;
48	    private final VetRepository vetRepository;
49	    private final OwnerRepository ownerRepository;
50	    private final VisitRepository visitRepository;
51	    private final SpecialtyRepository specialtyRepository;
52	    private final PetTypeRepository petTypeRepository;
53	    private final MemberIdGenerator memberIdGenerator;
54	    private final HouseholdIdGenerator householdIdGenerator;
55	    private final OwnerMapper ownerMapper;
56	
57	    public ClinicServiceImpl(
58	        PetRepository petRepository,
59	        VetRepository vetRepository,
60	        OwnerRepository ownerRepository,
61	        VisitRepository visitRepository,
62	        SpecialtyRepository specialtyRepository,
63	        PetTypeRepository petTypeRepository,
64	        MemberIdGenerator memberIdGenerator,
65	        HouseholdIdGenerator householdIdGenerator,
66	        OwnerMapper ownerMapper) {
67	        this.petRepository = petRepository;
68	        this.vetRepository = vetRepository;
69	        this.ownerRepository = ownerRepository;
70	        this.visitRepository = visitRepository;
71	        this.specialtyRepository = specialtyRepository;
72	        this.petTypeRepository = petTypeRepository;
73	        this.memberIdGenerator = memberIdGenerator;
74	        this.householdIdGenerator = householdIdGenerator;
75	        this.ownerMapper = ownerMapper;
76	    }
77	
78	    @Override
