package org.springframework.samples.petclinic.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.stereotype.Component;

/**
 * Enqueues the welcome notification for a newly created owner by emitting a line to the dedicated
 * {@code NOTIFY} logger, keeping the notification side-effect separate from the create business
 * logic and from the {@link OwnerAuditor audit} side-effect.
 */
@Component
public class WelcomeNotifier {

    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    /**
     * Enqueue the welcome notification for a freshly created owner: a {@code NOTIFY} line carrying
     * the owner's id and its {@linkplain Owner#getMemberId() member id}.
     */
    public void enqueueWelcome(Owner owner) {
        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
    }
}

